-- Generated by npm run db:prepare. For a NEW, empty Signal database only.
-- Existing projects: apply only missing numbered migrations. No tables are dropped.
begin;

-- Source: 01_profiles.sql
-- Stage 03: user profiles and automatic creation after registration.

create table public.profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  display_name text not null default '' check (length(display_name) <= 100),
  created_at timestamptz not null default now()
);
alter table public.profiles enable row level security;
create policy profiles_select on public.profiles for select to authenticated using (auth.uid() = id);
create policy profiles_update on public.profiles for update to authenticated using (auth.uid() = id) with check (auth.uid() = id);
create function public.handle_new_user() returns trigger language plpgsql security definer set search_path = '' as $$
begin
  insert into public.profiles(id) values (new.id);
  return new;
end;
$$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
revoke all on function public.handle_new_user() from public;

-- Source: 02_projects.sql
-- Stage 05: structured content projects.

create table public.projects (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  title text not null check (length(title) between 3 and 160),
  kind text not null check (kind in ('video', 'channel', 'stream')),
  content jsonb not null check (jsonb_typeof(content) = 'object'),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
alter table public.projects enable row level security;
-- Access stays closed until the policies in the next migration are installed.

-- Source: 03_policies.sql
-- Stage 08: project isolation. Never use a service-role key in the application.

create policy projects_select on public.projects for select to authenticated using (auth.uid() = user_id);
create policy projects_insert on public.projects for insert to authenticated with check (auth.uid() = user_id);
create policy projects_update on public.projects for update to authenticated using (auth.uid() = user_id) with check (auth.uid() = user_id);
create policy projects_delete on public.projects for delete to authenticated using (auth.uid() = user_id);
revoke all on public.profiles, public.projects from anon;
grant select, update on public.profiles to authenticated;
grant select, insert, update, delete on public.projects to authenticated;

-- Source: 04_indexes.sql
-- Stage 11: support per-user project lists and reliable update timestamps.

create index projects_user_created_idx on public.projects(user_id, created_at desc);
create function public.touch_updated_at() returns trigger language plpgsql set search_path = '' as $$
begin
  new.updated_at = now();
  return new;
end;
$$;
create trigger projects_updated_at before update on public.projects for each row execute function public.touch_updated_at();

-- Source: 05_constraints.sql
-- Stage 13: bound payload size and enforce a readable project shape.

alter table public.projects add constraint projects_content_size check (octet_length(content::text) <= 16384);
alter table public.projects add constraint projects_content_shape check (
  content ?& array['topic', 'kind', 'titles', 'description', 'tags', 'checklist']
  and jsonb_typeof(content->'titles') = 'array'
  and jsonb_typeof(content->'tags') = 'array'
  and jsonb_typeof(content->'checklist') = 'array'
  and jsonb_typeof(content->'description') = 'string'
  and content->>'kind' = kind
  and content->>'topic' = title
);

-- Source: 06_admin.sql
-- Admin access is granted only by the project owner in SQL Editor.

create table public.user_roles (
  user_id uuid primary key references auth.users(id) on delete cascade,
  role text not null check (role = 'admin')
);
alter table public.user_roles enable row level security;
revoke all on public.user_roles from anon, authenticated;

create function public.is_signal_admin() returns boolean
language sql stable security definer set search_path = '' as $$
  select exists(select 1 from public.user_roles where user_id = auth.uid() and role = 'admin');
$$;
revoke all on function public.is_signal_admin() from public;
grant execute on function public.is_signal_admin() to authenticated;

create policy profiles_admin_read on public.profiles for select to authenticated using (public.is_signal_admin());
create policy projects_admin_read on public.projects for select to authenticated using (public.is_signal_admin());

create table public.app_settings (
  id integer primary key check (id = 1),
  announcement_ru text not null default '' check (length(announcement_ru) <= 300),
  announcement_en text not null default '' check (length(announcement_en) <= 300),
  version integer not null default 1 check (version > 0)
);
insert into public.app_settings(id) values (1);
alter table public.app_settings enable row level security;
create policy settings_read on public.app_settings for select to anon, authenticated using (true);
create policy settings_admin_update on public.app_settings for update to authenticated using (public.is_signal_admin()) with check (public.is_signal_admin());
grant select on public.app_settings to anon, authenticated;
grant update (announcement_ru, announcement_en, version) on public.app_settings to authenticated;

create table public.admin_events (
  id uuid primary key default gen_random_uuid(),
  actor_id uuid references auth.users(id) on delete set null,
  action text not null,
  created_at timestamptz not null default now()
);
alter table public.admin_events enable row level security;
create policy events_admin_read on public.admin_events for select to authenticated using (public.is_signal_admin());
grant select on public.admin_events to authenticated;
create function public.audit_settings_change() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  insert into public.admin_events(actor_id, action) values (auth.uid(), 'announcement_updated');
  return new;
end;
$$;
revoke all on function public.audit_settings_change() from public;
create trigger settings_audit after update on public.app_settings for each row execute function public.audit_settings_change();

create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path = '' as $$
begin
  insert into public.profiles(id, display_name) values (new.id, left(coalesce(new.raw_user_meta_data->>'display_name', new.raw_user_meta_data->>'full_name', ''), 100));
  return new;
end;
$$;

commit;
